"""Renders tracking.md, the coverage table of every catalogue factor and what its trials found."""

import json
from pathlib import Path

from . import catalogue, record
from .mutators import MUTATORS

FILE_NAME = "tracking.md"
DEFAULT_OUT = Path(__file__).with_name(FILE_NAME)
HEADER = (
    "<!-- Generated by performance_tuning/tracking.py from factors.yaml and the "
    "trial records; do not edit by hand. -->"
)
COLUMNS = (
    "name",
    "mutator",
    "unit",
    "priority",
    "status",
    "trials",
    "headline",
    "verdict",
)
NO_MUTATOR = "needs a mutator"
MISSING = "–"


def _cell(text) -> str:
    return " ".join(str(text).split()).replace("|", "\\|")


def _condition(condition) -> str:
    if isinstance(condition, str):
        return condition
    return json.dumps(condition, sort_keys=True)


def _number(value) -> str:
    return MISSING if value is None else f"{value:.1f}"


def _headline(results) -> str:
    return "<br>".join(
        f"{_cell(_condition(c['condition']))}: "
        f"{_number(c['minutes_per_whole_cell'])} min/whole cell, "
        f"{_number(c['whole_cells_per_slice'])} whole cells/slice"
        for c in results["conditions"]
    )


def _labelled(closed, text_of) -> str:
    if len(closed) == 1:
        return text_of(closed[0])
    return "<br>".join(f"{t.id}: {text_of(t)}" for t in closed)


def _row(factor, trials) -> list:
    closed = [
        t
        for t in trials
        if t.primary_factor == factor.name and t.status == "closed" and t.results
    ]
    if factor.mutator is None:
        mutator, unit = NO_MUTATOR, ""
    else:
        cls = MUTATORS[factor.mutator]
        mutator, unit = cls.__name__, cls.unit
    plain = [
        factor.name,
        mutator,
        unit,
        factor.priority,
        factor.status,
        ", ".join(factor.trials),
    ]
    return [_cell(text) for text in plain] + [
        _labelled(closed, lambda t: _headline(t.results)),
        _labelled(closed, lambda t: _cell(t.verdict or "")),
    ]


def render(factors, trials) -> str:
    lines = [
        HEADER,
        "",
        "# Performance tuning coverage",
        "",
        "| " + " | ".join(COLUMNS) + " |",
        "|" + "---|" * len(COLUMNS),
    ]
    for factor in factors:
        lines.append("| " + " | ".join(_row(factor, trials)) + " |")
    return "\n".join(lines) + "\n"


def regenerate(
    catalogue_path=catalogue.DEFAULT_PATH, trials_dir=record.TRIALS_DIR, out=DEFAULT_OUT
) -> Path:
    out = Path(out)
    out.write_text(
        render(catalogue.load(catalogue_path), record.all_trials(trials_dir))
    )
    return out
